/* From Uiverse.io by Amine-maker - Tags: active, input, account */
.__UIV_SCOPE__ #label-input {
  transition: all 0.1s ease-in-out;
  color: #2c2c54;
  position: absolute;
  top: 30%;
  left: 18px;
  transform: scale(0.95);
  opacity: 1;
  pointer-events: none;
}

.__UIV_SCOPE__ .input-base {
  border-radius: 10px;
}

.__UIV_SCOPE__ #input:focus ~ label#label-input,
.__UIV_SCOPE__ #input:not(:placeholder-shown) ~ #label-input {
  top: -20% !important;
  left: 2px !important;
  transform: scale(0.8);
  background: white;
  color: black;
  padding: 0 6px;
  opacity: 1;
}

.__UIV_SCOPE__ #input {
  transition: outline 0.2s ease;
  font-size: 1rem;
  outline-color: var(--button-text);
  outline: unset;
  border: 1px solid #bbbbbb;
  padding: 17px 10px 10px 17px;
  width: 100%;
}

.__UIV_SCOPE__ #input:focus {
  box-shadow: 0 0 0 1px #e8e8e8, 0 0 0 3px rgb(92, 127, 202);
}

.__UIV_SCOPE__ .relative {
  position: relative;
}
